const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
let storageOK=true,state={current:0,completed:[],sessions:{}},view='classroom',expanded=0,editorOpen=false,mode='shell',lab=null,log=[],engine,session,recall=0,filterStage='all',filterQuery='',learningTab='learn';
try{const v=JSON.parse(localStorage.getItem('ops-learning-v1'));if(v&&Number.isInteger(v.current)&&Array.isArray(v.completed)&&v.sessions&&typeof v.sessions==='object'){if(!v.catalogVersion||v.catalogVersion<3){const remap=id=>courses.findIndex(c=>c.title===legacyCourseTitles[id]);const sessions={};for(const [id,entry] of Object.entries(v.sessions)){const mapped=remap(Number(id));if(mapped>=0)sessions[mapped]=entry;}v.current=Math.max(0,remap(v.current));v.completed=v.completed.map(remap).filter(id=>id>=0);v.sessions=sessions;v.catalogVersion=3;}if(v.current>=0&&v.current<courses.length)state=v;}}catch(e){storageOK=false;}

// A completed attempt must have both operation evidence and a graded correct answer.
state.completed=[...new Set(state.completed)].filter(id=>{const c=courses[id],a=state.sessions[id];return c&&a&&a.step===c.steps.length&&a.quiz&&(a.selected??c.answer)===c.answer;});
if(!courseUnlocked(state.current))state.current=nextId();
function courseUnlocked(id){return Number.isInteger(id)&&id>=0&&id<courses.length&&id<=nextId();}
function tabUnlocked(tab){return tab==='learn'||tab==='practice'&&session.read||tab==='quiz'&&session.read&&session.step===current().steps.length;}
function labUnlocked(l){return courses.filter(c=>c.stage<=l.stage).every(c=>state.completed.includes(c.id));}
function goToTab(tab){if(!['learn','practice','quiz'].includes(tab))return false;if(!tabUnlocked(tab)){toast(tab==='practice'?'先读懂讲解，点击“我读懂了，开始练习”。':'先逐步完成所有操作，再进入通关小测。');return false;}learningTab=tab;save();render();return true;}

function save(){state.catalogVersion=4;if(!lab)state.sessions[state.current]={...session,tab:learningTab,engine:engine};try{localStorage.setItem('ops-learning-v1',JSON.stringify(state));}catch(e){storageOK=false;}}
const labs=[
 {key:'web',title:'网站突然无法访问',stage:3,summary:'HTTP 请求失败，保留证据，检查服务，恢复后验证。',scene:'模拟告警：用户无法打开网站。你需要先读状态和日志，再恢复并验证。本练习不涉及真实服务器。',concept:'先判断是监听问题还是应用问题；服务未启动时使用 start，不必直接 restart。恢复之后以请求结果验证。',steps:[{task:'检查 nginx 状态',cmd:'systemctl status nginx',explain:'先发现 inactive，再考虑恢复动作。',output:'inactive'},{task:'读取服务日志',cmd:'journalctl -u nginx -n 20 --no-pager',explain:'保留服务停止的证据。',output:'Stopped'},{task:'在模拟环境启动服务',cmd:'systemctl start nginx',explain:'此时有证据表明服务未启动。'},{task:'验证网站响应',cmd:'curl -I http://localhost',explain:'恢复判断要有请求证据。',output:'200 OK'}],question:'服务恢复后仍然应该做什么？',options:['删除所有日志','分析停止原因并跟进防复发措施','什么都不做'],answer:1,note:'实战重点是观察 → 留证 → 恢复 → 验证 → 复盘。',source:'system'},
 {key:'sql',title:'撤销一次错误数据修改',stage:4,summary:'在事务内误改用户状态，发现后回滚并读回数据。',scene:'模拟数据库：你准备修改 Bob 的状态，在提交前决定撤销。目标是保存原始状态 inactive。',concept:'事务尚未提交时可通过 ROLLBACK 恢复；已提交修改要按业务补偿或恢复方案处理，不能假设回滚仍有效。',steps:[{task:'记录原始状态',cmd:'SELECT * FROM users WHERE id = 2;',explain:'改前读数据，确认影响对象。',output:'inactive'},{task:'开启事务',cmd:'START TRANSACTION;',explain:'演练数据保留事务快照。',output:'started'},{task:'修改 Bob 状态',cmd:"UPDATE users SET status = 'active' WHERE id = 2;",explain:'修改仍在未提交事务内。',output:'1 行'},{task:'撤销修改',cmd:'ROLLBACK;',explain:'恢复修改前的状态。',output:'rolled back'},{task:'读回原状态',cmd:'SELECT * FROM users WHERE id = 2;',explain:'用实际查询确认 inactive 已恢复。',output:'inactive'}],question:'这个练习能够回滚的前提是什么？',options:['事务尚未提交且修改可事务化','数据已经提交','任意数据库语句都可回滚'],answer:0,note:'真实场景需要结合存储引擎、连接、事务边界和审计记录。',source:'sql'},
 {key:'k8s',title:'Pod 镜像拉取失败',stage:7,summary:'读懂 ImagePullBackOff，检查事件，修正教学镜像。',scene:'模拟集群 learning 的 web Pod 使用了不存在的镜像标签。目标是通过事件定位，再恢复期望状态。',concept:'容器尚未创建时没有应用日志；先看 describe 的 Events。真实问题可能是镜像地址、凭据、镜像仓库或网络，本演练只模拟错误标签。',steps:[{task:'查看异常 Pod',cmd:'kubectl get pods -n learning',explain:'识别 ImagePullBackOff。',output:'ImagePullBackOff'},{task:'查看具体拉取事件',cmd:'kubectl describe pod web-7d9f -n learning',explain:'manifest unknown 指向镜像标签问题。',output:'manifest unknown'},{task:'修正模拟镜像',cmd:'kubectl set image deployment/web web=nginx:stable -n learning',explain:'真实变更还需同步受版本管理的配置。',output:'updated'},{task:'验证部署就绪',cmd:'kubectl rollout status deployment/web -n learning',explain:'真实环境需等待调度、启动和探针，本模拟立即完成。',output:'successfully'}],question:'在镜像没有拉取成功时，最有效的证据来自哪里？',options:['应用容器日志必然存在','Pod 的 Events 和镜像配置','所有用户表'],answer:1,note:'完成后在真实测试集群中复做，并记录排查时间线。',source:'k8s'}
];
function current(){return lab||courses[state.current];}
function restore(id){state.current=id;expanded=courses[id].stage;lab=null;view='classroom';editorOpen=false;const c=courses[id],saved=state.sessions[id];engine=new OpsEngine();if(saved?.engine&&typeof saved.engine.fs==='object'){const initialFs=engine.fs;Object.assign(engine,saved.engine);engine.fs={...initialFs,...saved.engine.fs};}const step=Math.max(0,Math.min(Number.isInteger(saved?.step)?saved.step:0,c.steps.length)),selected=Number.isInteger(saved?.selected)?saved.selected:saved?.quiz?c.answer:null;session={read:!!saved?.read||step>0||!!saved?.quiz,step,quiz:!!saved?.quiz&&selected===c.answer&&step===c.steps.length,selected,quizFeedback:saved?.quizFeedback||'',verified:saved?.verified?.step===step&&saved?.verified?.command===c.steps[step]?.cmd?saved.verified:null,verification:saved?.verification||null,draft:saved?.draft||''};learningTab=saved?.tab&&tabUnlocked(saved.tab)?saved.tab:session.quiz?'quiz':session.read?'practice':'learn';mode=firstIsSQL(c.steps[step]?.cmd||'')?'sql':'shell';recall=engine.history.length;log=[{type:'system',text:'运维练习室 / 本地教学模拟\n输入本课命令并观察结果。只有验证通过，才能点击“下一步”。\n环境与练习进度仅保存在当前设备。'}];if(session.verification){log.push({type:'command',text:session.verification.command},{type:session.verification.kind==='success'?'success':'error',text:session.verification.out||session.verification.message});}}
function nextId(){for(let i=0;i<courses.length;i++)if(!state.completed.includes(i))return i;return courses.length-1;}
function toast(t){$('notice').textContent=t;$('notice').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('notice').style.display='none',3300);}
function navHTML(){return `<header><button class="brand" data-action="view" data-view="classroom" aria-label="返回课程学习"><span class="brand-icon" aria-hidden="true">&gt;_</span><span>运维练习室<small>一间可以动手的教室</small></span></button><nav aria-label="主导航">${[['classroom','课程学习'],['roadmap','学习路线'],['manual','命令手册'],['labs','综合实战'],['demos','原理演示']].map(([v,t])=>`<button data-action="view" data-view="${v}" class="${view===v?'active':''}" ${view===v?'aria-current="page"':''}><span class="nav-full">${t}</span><span class="nav-short">${({classroom:'课程',roadmap:'路线',manual:'手册',labs:'实战',demos:'演示'})[v]}</span></button>`).join('')}</nav><span class="saved">${storageOK?'进度保存在当前设备':'当前设备无法保存进度'}</span></header>${!storageOK?'<div class="storage-warning">浏览器存储不可用，当前练习仍可使用，但刷新后可能丢失进度。</div>':''}<div class="subbar"><div><strong>一次学一点，把基础练扎实</strong><small>Linux → SQL → 业务运维 → Kubernetes</small></div><div class="progress-group"><div class="progress-track" role="progressbar" aria-label="课程完成进度" aria-valuenow="${state.completed.length}" aria-valuemin="0" aria-valuemax="${courses.length}"><span style="width:${state.completed.length/courses.length*100}%"></span></div><span>${state.completed.length} / ${courses.length} 课完成</span></div></div>`;}
function sidebar(){return `<aside class="sidebar" aria-label="闯关目录"><div class="side-label">你的闯关路线 / ${stages.length} 个阶段</div>${stages.map((s,i)=>{const list=courses.filter(c=>c.stage===i),done=list.filter(c=>state.completed.includes(c.id)).length;return `<button class="stage-button ${current().stage===i?'selected':''}" data-action="expand" data-id="${i}" aria-expanded="${expanded===i}"><span class="stage-number">${String(i+1).padStart(2,'0')}</span><span>${s.name}</span><small>${done}/${list.length}</small></button>${expanded===i?`<div class="lesson-links">${list.map(c=>`<button data-action="lesson" data-id="${c.id}" ${courseUnlocked(c.id)?'':'disabled'} class="${!lab&&state.current===c.id?'selected':''} ${!courseUnlocked(c.id)?'locked':''}"><span class="${state.completed.includes(c.id)?'done':''}">${state.completed.includes(c.id)?'✓':courseUnlocked(c.id)?'○':'锁'}</span>${c.title}<small>${state.completed.includes(c.id)?'已通关':!lab&&state.current===c.id?'正在学':courseUnlocked(c.id)?'可开始':'待解锁'}</small></button>`).join('')}</div>`:''}`;}).join('')}<div class="side-note">读懂 → 逐步操作 → 通关小测。<br>上一关通过后，下一关才会解锁。<br><br>命令手册和原理演示可随时查阅。</div></aside>`;}
function taskHTML(){const c=current(),step=c.steps[session.step],v=session.verification;return `<section class="section task-section"><div><div class="task-head"><h2>一步一步，做出结果</h2><span>${session.step} / ${c.steps.length}</span></div>${step?`<div class="task-current"><span class="chip">操作 ${session.step+1} / ${c.steps.length} · ${session.verified?'已验证，等待继续':'正在练习'}</span><h3>${esc(step.task)}</h3><p>${esc(step.explain)}</p><div class="cmd-example"><code>${esc(step.cmd)}</code><button data-action="fill" ${session.verified?'disabled':''}>填入练习区</button></div>${referenceHTML(c,session.step,false)}<div class="verify-focus"><b>怎样算做对？</b><span>${step.output?'命令和当前任务匹配，且返回信息中看到「'+esc(step.output)+'」。':'命令与当前任务匹配，执行成功并校验模拟状态。'}</span></div><div class="operation-verdict ${v?.kind||'waiting'}" role="status"><strong>${v?esc(v.message):'还未验证：在练习区输入本步命令。'}</strong><span>${session.verified?'结果保留在终端里。读懂结果后，再点击下面的按钮。':v?'本步未通过，仍停留在操作 '+(session.step+1)+'。对照标准用法修改后重试。':'普通命令执行成功不代表完成当前任务。'}</span></div><button class="primary advance-step" data-action="advance-step" ${session.verified?'':'disabled'}>${session.step===c.steps.length-1?'确认结果，完成操作':'确认结果，进入下一步'}</button></div>`:'<div class="complete-banner"><strong>✓ 本关所有操作已完成</strong><p>现在用一道小测确认你理解了这些操作。答对才会解锁下一关。</p><button class="primary" data-action="learning-tab" data-tab="quiz">进入通关小测</button></div>'}<details class="step-checklist" open><summary>本关操作路线 · ${session.step}/${c.steps.length}</summary><div class="task-list">${c.steps.map((s,i)=>`<div class="task-row ${i===session.step?'current':''}"><span class="step-dot ${i<session.step?'done':''}">${i<session.step?'✓':i+1}</span><span>${esc(s.task)}${i===session.step&&session.verified?' · 已验证':''}</span></div>`).join('')}</div></details><button class="text-button" data-action="learning-tab" data-tab="learn">回看讲解与关联知识</button></div></section>`;}
function recordCompletion(){if(lab)return;const passed=session.read&&session.quiz&&session.selected===current().answer&&session.step===current().steps.length;if(passed){if(!state.completed.includes(state.current))state.completed.push(state.current);}else state.completed=state.completed.filter(id=>id!==state.current);}
function answerExplanation(c){return connectionFor(c)[3];}
function quizHTML(){const c=current(),allSteps=session.step===c.steps.length,passed=allSteps&&session.quiz&&session.selected===c.answer;return `<div class="section quiz-section"><div><div class="eyebrow">最后一步 · 理解才能通关</div><h2>把操作背后的道理说清楚</h2><p class="quiz-question">${esc(c.question)}</p><fieldset class="quiz-fieldset"><legend class="small-note">选一个答案，再点击“检查答案”。选项都可以点击。</legend><div class="quiz-options">${c.options.map((s,i)=>`<label for="answer-${i}" class="${session.selected===i?'is-selected':''}"><input id="answer-${i}" type="radio" name="answer" value="${i}" ${session.selected===i?'checked':''}><span class="answer-letter">${String.fromCharCode(65+i)}</span><span>${esc(s)}</span></label>`).join('')}</div><button class="primary" data-action="quiz" ${session.selected===null?'disabled':''}>检查答案</button></fieldset><div id="quiz-feedback" class="quiz-feedback ${session.quizFeedback?(passed?'correct':'incorrect'):''}" aria-live="polite">${session.quizFeedback?`<strong>${passed?'✓ 回答正确，本关通过':'这次没答对，本关还未通过'}</strong><p>${esc(session.quizFeedback)}</p>${!passed?'<button class="text-button" data-action="learning-tab" data-tab="learn">回看讲解，再试一次</button>':''}`:''}</div><div class="course-status"><span>${allSteps?'✓':'○'} 操作 ${session.step}/${c.steps.length}</span><span>${passed?'✓':'○'} 通关小测</span></div><div class="gate-result ${passed?'passed':''}"><strong>${passed?lab?'✓ 演练通过':'✓ 关卡 '+String(state.current+1).padStart(2,'0')+' 已通关':'下一关尚未解锁'}</strong><p>${passed?'操作与小测均已通过。点击按钮后才会进入下一关。':'答错或更换答案都会留在本关。请先检查新答案。'}</p><button class="primary" data-action="next" ${passed?'':'disabled'}>${lab?'返回综合实战':state.current===courses.length-1?'查看完整学习成果':passed?'进入关卡 '+String(state.current+2).padStart(2,'0'):'通过小测后继续'}</button></div><details class="quiz-review"><summary>回顾关联知识</summary>${relatedHTML(c)}</details></div></div>`;}
function benchHTML(){const step=current().steps[session.step];return `<aside class="workbench" aria-label="交互练习区"><div class="bench-label"><span>练习工作台</span><span class="sim-badge">教学模拟环境</span></div><div class="bench-task"><span class="eyebrow">${step?'YOUR NEXT STEP / 当前操作':'PRACTICE COMPLETED / 练习完成'}</span><strong>${step?esc(step.task):'所有操作已完成，准备做通关小测。'}</strong>${step?`<div class="cmd-example"><code>${esc(step.cmd)}</code><button data-action="fill" ${session.verified?'disabled':''}>填入</button></div>`:'<button class="secondary" data-action="learning-tab" data-tab="quiz">去做小测</button>'}</div><div class="terminal"><div class="term-toolbar"><span class="term-mark">${mode==='sql'?'MYSQL / learning':'student@ops-lab'}</span><div class="term-actions"><button data-action="mode" data-mode="shell" aria-pressed="${mode==='shell'}">命令行</button><button data-action="mode" data-mode="sql" aria-pressed="${mode==='sql'}">SQL</button></div></div><div id="term-output" class="term-output" role="log" aria-label="终端结果" aria-live="polite"></div><form id="command-form" class="term-form"><label class="input-label" for="command">${mode==='sql'?'在这里输入 SQL 语句':'在这里输入当前步骤的命令'}</label><div class="input-row"><span class="prompt" aria-hidden="true">${mode==='sql'?'SQL>':'$'}</span><textarea id="command" ${session.verified?'disabled':''} rows="2" aria-label="${mode==='sql'?'SQL 语句':'命令输入'}" spellcheck="false" autocapitalize="off" autocomplete="off" placeholder="${mode==='sql'?'例如：SELECT * FROM users;':'例如：pwd'}"></textarea></div><div class="term-bottom"><small class="keyboard-tip">Enter 执行 · Shift+Enter 换行</small><small class="touch-tip">输入后点击右侧按钮</small><button class="run" type="submit" ${session.verified?'disabled':''}>${session.verified?'本步已通过':'执行并验证'}</button></div></form><div class="term-caption" id="cwd-label">${esc(engine.cwd)} · 只支持课程里的命令与 SQL</div></div>${session.verified?`<div class="bench-step-gate"><strong>✓ 本步验证通过</strong><p>先读终端结果，再确认进入下一步。</p><button class="primary" data-action="advance-step">${session.step===current().steps.length-1?'确认结果，完成操作':'确认结果，进入下一步'}</button></div>`:''}<div class="bench-tools"><button class="secondary" data-action="hint">看提示</button><button class="secondary" data-action="editor">${editorOpen?'收起编辑器':'编辑练习文件'}</button><button class="text-button" data-action="reset">重新练一次</button></div>${editorOpen?editorHTML():''}<details class="guide-card"><summary>在这里，你可以安心练习</summary><p>所有结果都是本地教学模拟，不连接真实服务器或数据库。</p><p>输入 <code>help</code> 查看支持范围。真实安装、网络、调度和备份耗时不会在这里发生。</p></details><details class="guide-card"><summary>迁移到真实环境时，留意什么？</summary><p>${esc(current().note)}</p><a target="_blank" rel="noopener noreferrer" href="${sources[current().source][1]}">${sources[current().source][0]}</a></details></aside>`;}
function editorHTML(){const file=current().stage===7?'deployment.yaml':current().title.includes('条件')?'condition.sh':current().title.includes('循环')?'services.sh':'health.sh';return `<div class="editor"><label for="editor-file">练习文件</label><select id="editor-file">${['health.sh','condition.sh','services.sh','deployment.yaml','notes.txt'].map(f=>`<option ${f===file?'selected':''}>${f}</option>`).join('')}</select><textarea id="editor-content" aria-label="练习文件内容" spellcheck="false">${esc(engine.fs['/home/student/'+file]||'')}</textarea><p class="small-note">保存到模拟家目录。Shell 只运行内置样例；YAML 仅支持课程模板。真实测试需使用 Bash 或 K8s 集群。</p><button class="primary" data-action="save-file">保存练习文件</button></div>`;}
